const $=id=>document.getElementById(id);
const supa=()=>window.OPQ_CLOUD?.ready&&window.OPQ_SUPABASE?window.OPQ_SUPABASE:null;
let mode='signin';
let passwordRecoveryMode=false;
const accountRedirectUrl=()=>new URL('/account.html?password-reset=1',location.origin).toString();
function showPasswordReset(message=''){ $('authCard').classList.remove('hidden');$('ordersCard').classList.add('hidden');$('authForm').classList.add('hidden');$('resetPasswordForm').classList.remove('hidden');$('authHeading').textContent='Reset your password';$('resetPasswordMessage').textContent=message; }
const labels={pending:'Pending review',confirmed:'Confirmed',awaiting_payment:'Awaiting payment',in_progress:'In progress / tailoring',ready:'Ready for collection',out_for_delivery:'Out for delivery',delivered:'Delivered',cancelled:'Cancelled'};
const money=n=>'KSh '+Number(n||0).toLocaleString('en-KE');
function setMode(next){mode=next;$('authHeading').textContent=mode==='signup'?'Create your account':'Sign in to your account';$('authSubmit').textContent=mode==='signup'?'Create account':'Sign in';$('toggleMode').textContent=mode==='signup'?'I already have an account':'Create an account';$('forgotPasswordButton').classList.toggle('hidden',mode!=='signin');$('signupPasswordGuidance').classList.toggle('hidden',mode!=='signup');['nameWrap','phoneWrap','regionWrap','confirmPasswordWrap'].forEach(id=>$(id).classList.toggle('hidden',mode!=='signup'));['fullName','accountPhone','accountRegion','confirmPassword'].forEach(id=>$(id).required=mode==='signup');if(mode!=='signup')$('confirmPassword').value='';$('password').autocomplete=mode==='signup'?'new-password':'current-password';updatePasswordGuidance('password','signupPasswordGuidance');}
$('toggleMode').onclick=()=>setMode(mode==='signin'?'signup':'signin');
$('forgotPasswordButton').onclick=async()=>{const db=supa(),email=$('email').value.trim();if(!db){$('authMessage').textContent='The store connection is unavailable. Please try again later.';return}if(!email){$('authMessage').textContent='Enter your account email address first.';$('email').focus();return}const button=$('forgotPasswordButton');button.disabled=true;$('authMessage').textContent='Sending password reset email…';try{const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:accountRedirectUrl()});if(error)throw error;$('authMessage').textContent='If an account exists for that email, a password reset link will be sent. Check your inbox and spam folder.';}catch(err){$('authMessage').textContent=err.message||'Could not request a password reset.'}finally{button.disabled=false}};
$('resetPasswordForm').onsubmit=async e=>{e.preventDefault();const db=supa(),password=$('newPassword').value,confirm=$('newPasswordConfirm').value;if(!db){$('resetPasswordMessage').textContent='The store connection is unavailable. Please try again later.';return}if(!strongPassword(password)){$('resetPasswordMessage').textContent='Your password does not meet all the security requirements. Please check the list above.';return}if(password!==confirm){$('resetPasswordMessage').textContent='The passwords do not match.';return}const button=$('saveNewPassword');button.disabled=true;$('resetPasswordMessage').textContent='Updating your password…';try{const {error}=await db.auth.updateUser({password});if(error)throw error;passwordRecoveryMode=false;$('resetPasswordForm').classList.add('hidden');$('authForm').classList.remove('hidden');$('resetPasswordMessage').textContent='';$('authMessage').textContent='Your password has been updated successfully. You are now signed in.';history.replaceState(null,'',location.pathname);await loadAccount();}catch(err){$('resetPasswordMessage').textContent=err.message||'Could not update your password.'}finally{button.disabled=false}};
$('cancelPasswordReset').onclick=()=>{passwordRecoveryMode=false;$('resetPasswordForm').classList.add('hidden');$('authForm').classList.remove('hidden');setMode('signin');$('authMessage').textContent='You can now sign in with your existing password.';history.replaceState(null,'',location.pathname)};
 // Customer-only password visibility controls. The admin sign-in form is intentionally unchanged.
 function attachPasswordToggle(inputId,buttonId){const field=$(inputId),button=$(buttonId);if(!field||!button)return;button.onclick=()=>{const reveal=field.type==='password';field.type=reveal?'text':'password';button.setAttribute('aria-pressed',String(reveal));button.setAttribute('aria-label',reveal?'Hide password':'Show password');button.title=reveal?'Hide password':'Show password';button.textContent=reveal?'🙈':'👁️';};}
 [['password','togglePasswordVisibility'],['confirmPassword','toggleConfirmPasswordVisibility'],['newPassword','toggleNewPasswordVisibility'],['newPasswordConfirm','toggleNewPasswordConfirmVisibility']].forEach(([inputId,buttonId])=>attachPasswordToggle(inputId,buttonId));
 function passwordRules(value){return {length:value.length>=8,upper:/[A-Z]/.test(value),lower:/[a-z]/.test(value),number:/[0-9]/.test(value),special:/[^A-Za-z0-9]/.test(value)};}
 function updatePasswordGuidance(inputId,guidanceId){const input=$(inputId),panel=$(guidanceId);if(!input||!panel)return;const rules=passwordRules(input.value);panel.querySelectorAll('[data-rule]').forEach(item=>item.classList.toggle('met',!!rules[item.dataset.rule]));}
 function strongPassword(value){return Object.values(passwordRules(value)).every(Boolean);}
 $('password').addEventListener('input',()=>updatePasswordGuidance('password','signupPasswordGuidance'));
 $('newPassword').addEventListener('input',()=>updatePasswordGuidance('newPassword','resetPasswordGuidance'));
$('authForm').onsubmit=async e=>{e.preventDefault();const db=supa();if(!db){$('authMessage').textContent='The store connection is unavailable. Please try again later.';return}
 const email=$('email').value.trim(),password=$('password').value;
 $('authSubmit').disabled=true;$('authMessage').textContent='Please wait…';
 try{
  if(mode==='signup'){
   const name=$('fullName').value.trim(),phone=$('accountPhone').value.trim(),region=$('accountRegion').value,confirmPassword=$('confirmPassword').value;if(name.length<2)throw new Error('Please enter your full name.');if(!strongPassword(password))throw new Error('Choose a stronger password using at least 8 characters, a capital letter, a small letter, a number and a special character such as @ or #.');if(phone.replace(/[^0-9]/g,'').length<7)throw new Error('Please enter a valid phone number, including its country code where possible.');if(!region)throw new Error('Please choose your region / country.');if(password!==confirmPassword)throw new Error('Your passwords do not match. Please check both fields.');
  const redirectTo=new URL('/account.html',location.origin);
redirectTo.searchParams.set('auth','confirmed');const {data,error}=await db.auth.signUp({email,password,options:{data:{full_name:name,phone,region},emailRedirectTo:redirectTo.toString()}});if(error)throw error;
   if(data.session){const p=new URLSearchParams(location.search);if(p.get('return')==='checkout'){location.href='index.html?checkout=1';return}$('authMessage').textContent='Account created. Loading your orders…';await loadAccount()}
   else $('authMessage').textContent='Account created. Check your email to confirm your address, then sign in.';
  }else{
   const {error}=await db.auth.signInWithPassword({email,password});if(error)throw error;
   const p=new URLSearchParams(location.search);if(p.get('return')==='checkout'){location.href='index.html?checkout=1';return}
   await loadAccount();
  }
 }catch(err){$('authMessage').textContent=err.message||'Could not authenticate.'}
 finally{$('authSubmit').disabled=false}
};

