function renderMeasurementFields(values={}){const wrap=$('measurementFields');if(!wrap)return;const garment=$('tailorGarment')?.value||'',fields=measurementSets[garment]||measurementSets.Other;wrap.innerHTML=fields.map(([label,key,help])=>'<label class="measurement-field"><strong>'+label+'</strong><small>'+help+'</small><input inputmode="decimal" type="number" min="0" step="0.1" id="measure-'+key+'" placeholder="Enter '+($('measurementUnit')?.value||'cm')+'"></label>').join('');$('measurementHelpNote').textContent=(garment?'For '+garment+': ':'General guide shown below. Choose a garment above for its exact measurement list. ')+ 'Use a soft tape and keep it level. Enter each number in '+($('measurementUnit')?.value||'cm')+'. Do not pull the tape tight. Leave unsure fields blank and request tailor assistance.';Object.entries(values).forEach(([key,value])=>{const el=$('measure-'+key);if(el)el.value=value;});}
function collectMeasurementValues(){const unit=$('measurementUnit')?.value||'cm',fields=measurementSets[$('tailorGarment')?.value]||[];const lines=fields.map(([label,key])=>{const el=$('measure-'+key);return el&&el.value.trim()?label+': '+el.value.trim()+' '+unit:''}).filter(Boolean);if($('needMeasurementHelp')?.checked)lines.push('Customer requests tailor assistance with measurements.');const extra=$('measurementOtherNotes')?.value.trim();if(extra)lines.push('Additional notes: '+extra);return lines.join('\n');}
function loadMeasurementValues(raw){renderMeasurementFields();const values={},remaining=[];String(raw||'').split(/\n/).forEach(line=>{const m=line.match(/^([^:]+):\s*([0-9.]+)\s*(cm|in)?$/i);if(!m){if(line.trim()&&!/requests tailor assistance/i.test(line))remaining.push(line);return;}const field=(measurementSets[$('tailorGarment').value]||[]).find(([label])=>label.toLowerCase()===m[1].toLowerCase());if(field){values[field[1]]=m[2];if(m[3])$('measurementUnit').value=m[3].toLowerCase();}else remaining.push(line);});renderMeasurementFields(values);if($('measurementOtherNotes'))$('measurementOtherNotes').value=remaining.join('\n');if(/requests tailor assistance/i.test(raw))$('needMeasurementHelp').checked=true;}
$('tailorGarment')?.addEventListener('change',()=>{const values={};Object.values(measurementSets).flat().forEach(([,key])=>{const el=$('measure-'+key);if(el&&el.value)values[key]=el.value;});renderMeasurementFields(values);});
$('measurementUnit')?.addEventListener('change',()=>{const values={};Object.values(measurementSets).flat().forEach(([,key])=>{const el=$('measure-'+key);if(el&&el.value)values[key]=el.value;});renderMeasurementFields(values);});
