window.printTailoringQuotation=id=>{const r=(window.customerTailoringCache||[]).find(item=>String(item.id)===String(id));if(!r||r.quoted_amount_kes===null||r.quoted_amount_kes===undefined){alert('This request does not have an agreed quotation yet.');return;}const quote=Number(r.quoted_amount_kes),depositRate=Number(r.deposit_percent??30),balanceRate=Number(r.balance_percent??70),deposit=quote*depositRate/100,balance=quote*balanceRate/100;const safe=escapeHtml;const date=value=>value?new Date(value).toLocaleDateString('en-KE',{year:'numeric',month:'long',day:'numeric'}):'—';const popup=window.open('','_blank','width=900,height=750');if(!popup){alert('Please allow pop-ups for this site to print or save your quotation.');return;}const documentHtml='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>P&Q Tailoring Quotation - '+safe(r.reference_code)+'</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#172b43;margin:0;background:#f3f6fa}.sheet{max-width:800px;margin:32px auto;padding:42px;background:#fff;border:1px solid #d8e1eb}.brand{background:#142b4a;color:#fff;padding:25px 28px;border-bottom:5px solid #76243d}.brand h1{margin:0 0 6px;font-family:Georgia,serif;font-size:27px}.brand p{margin:0;color:#e7edf5;font-size:12px;letter-spacing:.06em}.meta{display:flex;justify-content:space-between;gap:20px;margin:28px 0}.meta h2{margin:0 0 8px;color:#76243d;font-size:22px}.muted{color:#64748b;font-size:12px;line-height:1.6}.details{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:20px 0}.detail{padding:13px;background:#f5f8fc;border:1px solid #e0e8f0;border-radius:7px}.detail span{display:block;color:#64748b;font-size:10px;text-transform:uppercase;letter-spacing:.06em;margin-bottom:5px}.detail strong{font-size:13px}.total{margin:24px 0;padding:22px;background:#f8f3f5;border-left:5px solid #76243d}.total span{display:block;color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:.07em}.total strong{display:block;margin-top:7px;color:#76243d;font-size:30px}.breakdown{width:100%;border-collapse:collapse;margin:18px 0}.breakdown th,.breakdown td{padding:14px;border-bottom:1px solid #e0e8f0;text-align:left}.breakdown th{background:#f5f8fc;color:#294967;font-size:11px}.breakdown td:last-child{text-align:right;font-weight:700}.note{margin-top:26px;padding:16px;background:#f5f8fc;border-radius:7px;font-size:12px;line-height:1.7}.footer{margin-top:34px;padding-top:16px;border-top:1px solid #d8e1eb;color:#64748b;font-size:11px;line-height:1.7}.actions{text-align:right;margin:0 auto 20px;max-width:800px}.actions button{background:#76243d;color:#fff;border:0;border-radius:6px;padding:11px 18px;font-weight:700;cursor:pointer}@media(max-width:600px){.sheet{margin:0;padding:20px}.meta{display:block}.details{grid-template-columns:1fr}.actions{padding:12px}}@media print{body{background:#fff}.sheet{margin:0 auto;border:0;padding:24px;max-width:none}.actions{display:none}@page{size:A4;margin:12mm}}</style></head><body><div class="actions"><button onclick="window.print()">Print / Save as PDF</button></div><main class="sheet"><header class="brand"><h1>OUTFITS WITH PEREZ &amp; QHASUKHU</h1><p>TAILORING • STYLE • CRAFT</p></header><section class="meta"><div><h2>Tailoring quotation</h2><div class="muted">A summary of your agreed custom tailoring price</div></div><div class="muted"><strong>Reference:</strong> '+safe(r.reference_code)+'<br><strong>Issued:</strong> '+date(new Date().toISOString())+'</div></section><section class="details"><div class="detail"><span>Customer</span><strong>'+safe(r.customer_name||'Customer')+'</strong></div><div class="detail"><span>Garment</span><strong>'+safe(r.garment_type||'Custom tailoring')+'</strong></div><div class="detail"><span>Country</span><strong>'+safe(r.country||'—')+'</strong></div><div class="detail"><span>Request date</span><strong>'+date(r.created_at)+'</strong></div><div class="detail"><span>Fabric preference</span><strong>'+safe(r.fabric||'Not specified')+'</strong></div><div class="detail"><span>Preferred colour</span><strong>'+safe(r.colour||'Not specified')+'</strong></div><div class="detail"><span>Desired completion</span><strong>'+date(r.desired_completion_date)+'</strong></div><div class="detail"><span>Request status</span><strong>'+safe((statusText[r.status]||r.status||'').replaceAll('_',' '))+'</strong></div></section><section class="total"><span>Agreed quotation total</span><strong>'+money(quote)+'</strong></section><table class="breakdown"><thead><tr><th>Payment stage</th><th>Rate</th><th>Amount (KES)</th></tr></thead><tbody><tr><td>Deposit</td><td>'+depositRate+'%</td><td>'+money(deposit)+'</td></tr><tr><td>Remaining balance</td><td>'+balanceRate+'%</td><td>'+money(balance)+'</td></tr><tr><th>Total agreed price</th><th>100%</th><th>'+money(quote)+'</th></tr></tbody></table><div class="note"><strong>Payment note</strong><br>The deposit and balance figures are calculated from the agreed quotation. Please follow the payment instructions provided directly by the P&amp;Q team. This document is a quotation summary, not a payment receipt.</div><footer class="footer"><strong>Outfits with Perez &amp; Qhasukhu</strong><br>For assistance, contact us on 0799281744 or 0721 292981.<br>Thank you for choosing P&amp;Q.</footer></main></body></html>';popup.document.open();popup.document.write(documentHtml);popup.document.close();popup.focus();popup.print();};
window.archiveTailoringRequest=async id=>{if(!confirm('Archive this completed or delivered request? It will remain saved and visible in your archived list.'))return;try{const {error}=await supa().rpc('archive_own_delivered_tailoring_request',{p_request_id:id});if(error)throw error;await loadTailoring();$('tailorMessage').textContent='Delivered request archived. Your record has not been deleted.';}catch(e){$('tailorMessage').textContent='Could not archive request: '+e.message}};

$('tailoringForm')?.addEventListener('submit',async e=>{
 e.preventDefault();const db=supa(),btn=$('tailorSubmit'),msg=$('tailorMessage');if(!db){msg.textContent='Store connection unavailable.';return;}btn.disabled=true;msg.textContent=editingTailoringId?'Saving corrections…':'Submitting…';let uploadedPath='';
 try{
  if(!$('tailorTerms').checked)throw new Error('Please accept the Terms & Policies before submitting.');const file=$('tailorImage').files[0];let imageUrl=editingTailoringId?(removeExistingImage?'':existingReferenceImage):'';
  if(file){if(file.size>6*1024*1024)throw new Error('Please use an image smaller than 6 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Use a JPG, PNG or WebP image.');
   const {data:{session}}=await db.auth.getSession();if(!session)throw new Error('Please sign in again.');const ext=file.type==='image/jpeg'?'jpg':file.type.split('/')[1];uploadedPath=session.user.id+'/'+crypto.randomUUID()+'.'+ext;
   const {error}=await db.storage.from('tailoring-references').upload(uploadedPath,file,{contentType:file.type,upsert:false});if(error)throw error;imageUrl=uploadedPath;
  }
  const fields={p_garment_type:$('tailorGarment').value,p_fabric:$('tailorFabric').value.trim(),p_colour:$('tailorColour').value.trim(),p_style_preferences:$('tailorStyle').value.trim(),p_measurements:collectMeasurementValues(),p_reference_image_url:imageUrl,p_special_instructions:$('tailorNotes').value.trim()+'\n[Terms & Policies accepted: P&Q-2026-01 at '+new Date().toISOString()+']',p_desired_completion_date:$('tailorDate').value||null,p_country:$('tailorCountry').value};
  if(editingTailoringId){
   const {data,error}=await db.rpc('update_customer_tailoring_request',{p_request_id:editingTailoringId,...fields,p_customer_name:$('tailorCustomerName').value.trim(),p_customer_phone:$('tailorCustomerPhone').value.trim()});if(error)throw error;
   const oldPath=data?.old_reference_image_url;if(oldPath&&oldPath!==imageUrl){const {error:removeError}=await db.storage.from('tailoring-references').remove([oldPath]);if(removeError)msg.textContent='Corrections saved, but the old private image could not be removed. Please contact the store.';}
   if(!msg.textContent.startsWith('Corrections saved'))msg.textContent='Corrections saved for '+data.reference_code+'. Your original request and reference number are unchanged.';
   resetTailoringEditor();
  }else{
   const {data,error}=await db.rpc('submit_tailoring_request_with_contact',{...fields,p_customer_name:$('tailorCustomerName').value.trim(),p_customer_phone:$('tailorCustomerPhone').value.trim()});if(error)throw error;
   const ref=data.reference_code;const waText='Hello Outfits with Perez & Qhasukhu. I have submitted a custom tailoring request. Reference: '+ref+'. Customer: '+$('tailorCustomerName').value.trim()+'. Phone: '+$('tailorCustomerPhone').value.trim()+'. Garment: '+$('tailorGarment').value+'. Country: '+$('tailorCountry').value+'. Please guide me on the next steps.';
   msg.innerHTML='Request submitted. Your reference is <strong>'+escapeHtml(ref)+'</strong>. The team will review it before confirming price, timing or deposit. <a href="https://wa.me/254799281744?text='+encodeURIComponent(waText)+'" target="_blank" rel="noopener">Continue on WhatsApp</a>';$('tailoringForm').reset();
  }
  await loadTailoring(db);
 }catch(err){if(uploadedPath)await db.storage.from('tailoring-references').remove([uploadedPath]);msg.textContent='Could not save request: '+err.message;}finally{btn.disabled=false;}
});
