window.submitReview=async id=>{const box=$('review-'+id),button=box?.parentElement?.querySelector('button'),rating=Number($('rating-'+id)?.value),review=box?.value.trim()||'';try{if(!supa())throw new Error('Store connection is unavailable.');if(review.length<5||review.length>1200)throw new Error('Please write between 5 and 1,200 characters.');if(!Number.isInteger(rating)||rating<1||rating>5)throw new Error('Choose a rating from 1 to 5 stars.');if(button)button.disabled=true;const {error}=await supa().rpc('submit_verified_product_review',{p_order_item_id:id,p_rating:rating,p_review_text:review});if(error)throw error;await refreshCustomerReviewStatuses();const form=box.closest('.review-form');form.innerHTML=reviewStatusMarkup(window.customerReviewStatuses?.['product:'+id]||{review_type:'product',subject:'Purchased product',rating,review_text:review,is_approved:false,created_at:new Date().toISOString()});}catch(e){const form=box?.closest('.review-form');let note=form?.querySelector('.review-feedback');if(!note&&form){note=document.createElement('p');note.className='review-feedback';form.append(note);}if(note)note.textContent='Review not submitted: '+e.message;else alert(e.message);if(button)button.disabled=false;}};
